import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CdjpmwdR.js";const c=JSON.parse('{"title":"Mesh-Shaped PKM: A Logseq-based Personal Knowledge System","description":"How I implemented a Mesh-Shaped PKM system on top of Logseq: input capture, task and note cycles, and feedback loops that turn recording into sustained capability growth.","frontmatter":{"category":"domain","date":"2022-12-01","title":"Mesh-Shaped PKM: A Logseq-based Personal Knowledge System","description":"How I implemented a Mesh-Shaped PKM system on top of Logseq: input capture, task and note cycles, and feedback loops that turn recording into sustained capability growth.","tags":["domain","PKM","logseq"],"image":"https://pic3.zhimg.com/v2-e53cc5d58b612b5154574f0eb2110d72_r.jpg"},"headers":[],"relativePath":"en/blogs/2022/202212-logseq-pkm.md","filePath":"en/blogs/2022/202212-logseq-pkm.md"}'),i={name:"en/blogs/2022/202212-logseq-pkm.md"};function s(n,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><img src="https://pic3.zhimg.com/v2-e53cc5d58b612b5154574f0eb2110d72_r.jpg" alt=""></p><p>After writing <a href="https://zhuanlan.zhihu.com/p/575842220" target="_blank" rel="noreferrer">&quot;Mesh-Shaped: How to Grow as a Cloud-Native Developer&quot;</a> earlier this year, I have been iterating on my personal knowledge management (PKM) system.</p><blockquote><p>The way you manage knowledge reflects how you think — and your thinking path determines output quality.</p></blockquote><p>The current workflow has been stable for a while. It combines tools, methods, and collaboration habits. This article breaks it down visually so you can reuse modules as needed.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/80/v2-0a99df5b67b41531e39dd8f9c5e7bb23_1440w.webp" alt=""></p><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><ul><li><a href="https://book.douban.com/subject/35503571/" target="_blank" rel="noreferrer">How to Take Smart Notes</a></li><li>OKR</li><li>Logic trees</li></ul><h3 id="input-types" tabindex="-1">Input Types <a class="header-anchor" href="#input-types" aria-label="Permalink to &quot;Input Types&quot;">​</a></h3><ul><li><strong>Task input</strong>: goal‑oriented work with clear deliverables and time windows (SMART principle).</li><li><strong>Knowledge input</strong>: research, exploration, and reading around a topic, often with attachments (books, papers, images, slides).</li></ul><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><ul><li><strong>GoFullPage</strong>: Chrome extension for full‑page screenshots.</li><li><strong>MarkDownload</strong>: Chrome extension to save pages or selections as markdown for Logseq.</li><li><strong>Cubox</strong>: Chrome/iOS/WeChat multi‑end collector and media box.</li></ul><blockquote><p>Cubox is powerful enough that if your ratio of collecting &gt; producing is high, using Cubox alone can work. I use Cubox as an inbox: when I see an article or thread worth keeping, I send it to Cubox first and later consume it via GTD/Logseq.</p></blockquote><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>Logseq is the core. Combined with card‑style notes, I separate pages by role:</p><ul><li><strong>Journey</strong>: daily journal pages generated by Logseq; good for scratch notes. TODOs are the only thing that must be tracked.</li><li><strong>Note</strong>: regular pages.</li><li><strong>Project</strong>: also pages, but with prefixes to indicate project scope.</li><li><strong>OKR</strong>: pages organized via tags/hierarchy/query to track objectives.</li></ul><p><img src="https://pic3.zhimg.com/80/v2-d99183cdf27244b27bf6499e9b3f6e6e_1440w.webp" alt="OKR Hierarchy"></p><h2 id="iteration" tabindex="-1">Iteration <a class="header-anchor" href="#iteration" aria-label="Permalink to &quot;Iteration&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/80/v2-28beb58c07769b2e95fb85572e6ba290_1440w.webp" alt="iteration"></p><h3 id="methods-1" tabindex="-1">Methods <a class="header-anchor" href="#methods-1" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><ul><li>OKR</li><li>GTD (Getting Things Done)</li><li>Mesh‑Shaped mindset</li></ul><h3 id="task-space" tabindex="-1">Task Space <a class="header-anchor" href="#task-space" aria-label="Permalink to &quot;Task Space&quot;">​</a></h3><ul><li><strong>OKR</strong>: as above.</li><li><strong>Roadmap</strong>: monthly breakdown of OKRs into executable tasks.</li><li><strong>GTD</strong>: categorized TODO management.</li></ul><p>Logseq queries pull tasks by priority, tag, keywords, and status.</p><p><img src="https://pic4.zhimg.com/80/v2-bb9523567c2e2804054f9f552d3051bf_1440w.webp" alt=""></p><p>You can also wire key queries into your Journey template so critical items show on each day’s front page.</p><p><img src="https://pic3.zhimg.com/80/v2-125cdaa60f9d7dc17a4f99841d91786e_1440w.webp" alt=""></p><h3 id="note-space" tabindex="-1">Note Space <a class="header-anchor" href="#note-space" aria-label="Permalink to &quot;Note Space&quot;">​</a></h3><p>The core is treating <strong>permanent notes</strong> as the real knowledge base, following smart‑notes style:</p><ul><li>Journey drafts can be disposable (unfinished TODOs are still caught by GTD queries).</li><li>Project/Book pages often act as aggregators.</li><li>Permanent notes are the real assets.</li></ul><p>A note landing in &quot;permanent&quot; does not mean it will stay useful forever:</p><ul><li>Structure matters: Logseq’s outliner pushes toward tree‑like organization inside a page. When a page grows large, split by sections (quadrants) or child pages (hierarchy).</li><li>Only <strong>linked</strong> knowledge is effective knowledge. The more associations you create — even playful ones like &quot;Agile project management applied to home renovation&quot; — the deeper it sticks and the more cross‑domain reuse you get.</li></ul><p><img src="https://pic2.zhimg.com/80/v2-0657aa86ae9b1b880ef578bd69d24a5d_1440w.webp" alt=""></p><h3 id="other-tools" tabindex="-1">Other Tools <a class="header-anchor" href="#other-tools" aria-label="Permalink to &quot;Other Tools&quot;">​</a></h3><ul><li><strong>GitHub</strong>: backup repo; you can also export Logseq and host a double‑linked graph site with GitHub Pages.</li><li><strong>GoodNotes, KOReader, WeChat Reading, Apple Books</strong>: for long‑form reading (books, English papers, annotated slides) an iPad + Pencil workflow can be more comfortable than Logseq’s builtin PDF viewer.</li></ul><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p><img src="https://pic1.zhimg.com/80/v2-84a9ff2439dac7d05696d5d7b426d95c_1440w.webp" alt=""></p><h3 id="methods-2" tabindex="-1">Methods <a class="header-anchor" href="#methods-2" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><ul><li>Feynman technique.</li><li>Agile personal productivity.</li><li>Other ideas in the diagram.</li></ul><h3 id="output-1" tabindex="-1">Output <a class="header-anchor" href="#output-1" aria-label="Permalink to &quot;Output&quot;">​</a></h3><ul><li>The key is <strong>feedback</strong>: publishing forces you to re‑structure knowledge; feedback forces you to re‑shape models.</li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><blockquote><p>“If knowledge is neither stored nor learned in isolation, but collected into a network of ideas — a latticework of mental models — then new information becomes easier to understand, remember, and retrieve.”</p></blockquote><h3 id="only-when-individuals-build-networks-can-networks-form-around-them" tabindex="-1">&quot;Only when individuals build networks, can networks form around them&quot; <a class="header-anchor" href="#only-when-individuals-build-networks-can-networks-form-around-them" aria-label="Permalink to &quot;&quot;Only when individuals build networks, can networks form around them&quot;&quot;">​</a></h3><p><img src="https://pic4.zhimg.com/80/v2-a0fec4a76fb99fef7dbd5205d575839b_1440w.webp" alt="graph"></p><p>As you build a larger capability mesh, your environment — people, opportunities, projects — starts to organize around it. That is where PKM turns into real career leverage.</p>',46)])])}const g=t(i,[["render",s]]);export{c as __pageData,g as default};
